(()=>{const form=document.getElementById('jarvis-connect-form');if(!form)return;const status=document.getElementById('jarvis-connect-status'),input=form.elements.namedItem('key'),save=form.querySelector('button[type=submit]'),remove=document.getElementById('jarvis-disconnect');let busy=false;const dialog=document.getElementById('jarvis-connect-dialog');function open(){if(!dialog.open)dialog.showModal();input.focus();}document.getElementById('jarvis-open-connect').onclick=open;document.getElementById('jarvis-close-connect').onclick=()=>dialog.close();window.addEventListener('jarvis-open-connect',open);const notify=()=>document.getElementById('fashion-jarvis-check')?.click();async function api(method,body){const r=await fetch('/api/jarvis/connection',{method,headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Connection unavailable');return d;}async function check(){try{const d=await api('GET');status.textContent=d.configured?'A private key is saved. Jarvis requests still depend on model permissions and account allowance.':'No key connected. Paste your full secret into the private field below.';remove.disabled=!d.configured||d.runtimeManaged;}catch(e){status.textContent=e.message;remove.disabled=true;}}
form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;save.disabled=remove.disabled=true;const key=input.value;input.value='';status.textContent='Validating and encrypting your key…';document.getElementById('jarvis-dialog-status').textContent=status.textContent;try{const d=await api('POST',{key});status.textContent=d.message;remove.disabled=false;notify();}catch(e){status.textContent=e.message;}finally{busy=false;save.disabled=false;document.getElementById('jarvis-dialog-status').textContent=status.textContent;}};remove.onclick=async()=>{if(busy||!confirm('Disconnect the saved key from Jarvis? This does not revoke it at OpenAI.'))return;busy=true;remove.disabled=save.disabled=true;try{await api('DELETE');status.textContent='Jarvis key disconnected.';notify();}catch(e){status.textContent=e.message;}finally{busy=false;save.disabled=false;await check();}};check();})();
